<?php
namespace qqworld_collector\module\collect_filter; class content_format extends filter { public function get_bulk_contents($items, $structure, $digits, $from, $to) { $preg = preg_match('/\(\*(\d*?)\)/i', $structure, $match); if ($preg) { $offset = $match[1] ? intval($match[1]) : 1; $pages = array($from, $to); sort($pages); for ($i=$pages[0]; $i<=$pages[1]; $i++) { $num = str_pad($i*$offset, $digits, "0", STR_PAD_LEFT); $items[] = preg_replace('/\(\*\d*?\)/i', $num, $structure); } } return $items; } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { extract($args); $structure = str_replace('(content)', $item, $structure ); $structure = apply_filters( 'qqworld-collector-collection-project-variable-filter', $structure, 0 ); $keywords = $GLOBALS['QC']->collector->engine->advanced_request->get_keywrods($item, $keyword, array( 'download_args' => $download_args, 'no_implode' => isset($no_implode) ? $no_implode : 0 )); if (!empty($keywords)) { $patterns = array(); $replacements = array(); foreach ($keywords as $pattern => $replacement) { $patterns[] = $pattern; $replacements[] = $replacement; } $from = isset($from) && $from ? $from : $item; $to = isset($to) && $to ? $to : $item; $item = str_replace($patterns, $replacements, $structure); $item = apply_filters( 'qqworld-collector-advanced-request-parse-new-link', $item ); $items = $this->get_bulk_contents(array(), $item, 1, $from, $to); if (!empty($items)) { $item = implode('', $items); } } else { $item = $structure; } return $item; } } ?>